css:
@page {
    size: 6cm 4cm;
    margin: 1mm;
}

.print-format {
    width: 58mm;
    height: 38mm;
    padding: 0 !important;
    margin: 0 !important;
    font-family: Arial, sans-serif;
    text-align: center;
}

.trial-label {
    width: 100%;
    height: 100%;
    overflow: hidden;
}

.factory-name {
    font-size: 8pt;
    font-weight: 700;
    margin-bottom: 1mm;
}

.trial-warning {
    font-size: 8pt;
    font-weight: 700;
    border-top: 1px solid #000;
    border-bottom: 1px solid #000;
    padding: 1mm 0;
    margin-bottom: 1.5mm;
}

.product-name {
    font-size: 13pt;
    font-weight: 700;
    line-height: 1.1;
    margin-bottom: 1mm;
}

.trial-title {
    font-size: 10pt;
    font-weight: 600;
    margin-bottom: 1.5mm;
}

.trial-meta {
    width: 100%;
    border-collapse: collapse;
    font-size: 8pt;
}

.trial-meta td:first-child {
    text-align: left;
}

.trial-meta td:last-child {
    text-align: right;
}
